import json,pathlib,html,statistics
root=pathlib.Path('docs/mission-22-1-evidence')
before=json.loads((root/'before.json').read_text());after=json.loads((root/'after.json').read_text())
base={'lune','sans-lune','couvert','pluie','orage','brume','neige','crepuscule','aube'}
rows=[]
for r in after['rows']:
 b=next(x for x in before['rows'] if x['scene']==r['scene'] and x.get('profile')==r.get('profile'))
 stem=r['scene']+('-'+r['profile'] if r.get('profile') and r['scene'] in base else '')
 rows.append({'label':r['scene'].replace('-',' ')+' · '+r.get('profile','équilibré'),'before':'before/'+stem+'.png','after':'after/'+stem+'.png','sameCamera':b['state']['camera']==r['state']['camera'],'camera':r['state']['camera'],'position':r['state']['position'],'date':r['state']['climate']['date'],'weather':r['state']['climate']['weather'],'light':r.get('light'),'pixels':{'before':b.get('pixels'),'after':r.get('pixels')}})
perf=json.loads((root/'performance.json').read_text())
timings=''.join('<tr><td>'+html.escape(r['station'])+'</td><td>'+r['profile']+'</td><td>'+str(r['people'])+'</td><td>'+f'{r["before"]["medianMs"]:.1f}'+'</td><td>'+f'{r["after"]["medianMs"]:.1f}'+'</td><td>'+f'{r["regressionPercent"]:+.2f} %'+'</td></tr>' for r in perf['rows'])
videos=[('Pont : marche et retour en course','pont-native.webm'),('Quai : contrôle natif complémentaire de rive','rive-native.webm'),('Famille : installation, pique-nique, retour et reprise','family-routine.webm'),('Assise individuelle complète','solo-routine.webm'),('Couple : activité et retour','couple-routine.webm')]
videos += [('Rencontre proche · '+name,'people/'+name+'.webm') for name in ['adulte','senior','enfant','amis']]
videos += [('Façade '+str(i+1)+' · '+v,'facades/'+v+'-'+str(i)+'-approche.webm')for i in range(3)for v in ['before','after']]
videos += [('Promenade ordinaire · '+v,'walk-'+v+'.webm')for v in ['opening','night','storm']]
videos += [('Contrôles tactiles dans Chromium','mobile-native.webm')]
if (root/'audio.json').exists():
 videos += [(r['title'],r['file'])for r in json.loads((root/'audio.json').read_text()).get('rows',[])]
cards=''.join('<figure><video controls preload="metadata" src="'+f+'"></video><figcaption>'+html.escape(title)+'</figcaption></figure>'for title,f in videos if (root/f).exists())
data=json.dumps(rows,ensure_ascii=False).replace('</',r'<\/')
text='''<!doctype html><html lang="fr"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Endless Earth · Mission 22.1</title><style>
*{box-sizing:border-box}body{margin:0;background:#101b19;color:#e4e4d8;font:16px/1.6 system-ui,sans-serif}main{max-width:1160px;margin:auto;padding:32px 20px 80px}h1,h2{font-family:Georgia,serif;font-weight:400;line-height:1.15}h1{font-size:clamp(36px,6vw,68px);max-width:900px}h2{font-size:32px;margin-top:56px}p{max-width:850px;color:#c4ccbf}small{color:#b7c1b4}a{color:#d7bc85;text-underline-offset:4px}select,input,button{font:inherit;min-height:44px}select{max-width:100%;width:100%;background:#20352e;color:#f0eedf;padding:10px;border:1px solid #687d6a;border-radius:8px}.comparison{position:relative;overflow:hidden;margin-top:18px;background:#08100d}.comparison img{display:block;width:100%}#after{position:absolute;inset:0;clip-path:inset(0 0 0 50%)}.badge{position:absolute;top:12px;background:#15251cdd;padding:4px 10px;border-radius:6px;font-size:13px}.left{left:12px}.right{right:12px}input[type=range]{width:100%;accent-color:#d7bc85}.films{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,330px),1fr));gap:18px}figure{margin:0;background:#1b2c26;padding:12px;border-radius:10px}video{width:100%;display:block;background:#080e0b}figcaption{font-size:14px;margin-top:8px}details{background:#1b2c26;padding:12px;border-radius:8px;margin-top:14px}summary{cursor:pointer}pre{overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}table{border-collapse:collapse;width:100%;font-size:14px}td,th{padding:9px;text-align:left;border-bottom:1px solid #405246}.scroll{overflow:auto}.note{border-left:3px solid #b3935e;padding-left:16px}.links{display:flex;gap:14px;flex-wrap:wrap}label{display:block;margin-bottom:8px}button{background:#294237;color:#eee9d7;border:1px solid #687d6a;border-radius:6px;padding:6px 12px}.controls{display:flex;gap:8px;margin-top:10px;flex-wrap:wrap}.kicker{letter-spacing:.16em;font-size:12px;color:#d7bc85}img{max-width:100%}
</style><main><p class="kicker">ENDLESS EARTH · MISSION 22.1</p><h1>Un monde plus continu.<br>Une nuit à parcourir.</h1><p>Comparaisons réelles du moteur, films natifs et résultats de validation. La base est la Mission 22 fusionnée par la PR #31. Les images du propriétaire orientent le diagnostic ; leurs positions exactes ne sont pas revendiquées.</p><nav class="links"><a href="../mission-22-1.md">Rapport complet</a><a href="#comparaisons">Comparaisons</a><a href="#films">Films et sons</a><a href="#mesures">Mesures</a><a href="#sources">Sources et limites</a></nav>
<h2 id="comparaisons">Même caméra, avant et après</h2><label for="scene">Scène et profil</label><select id="scene"></select><div class="comparison"><img id="before" alt="Mission 22, avant correction"><img id="after" alt="Mission 22.1, après correction"><span class="badge left">Mission 22</span><span class="badge right">Mission 22.1</span></div><label for="split">Déplacer la séparation</label><input id="split" type="range" min="0" max="100" value="50"><div class="controls"><button id="previous">Scène précédente</button><button id="next">Scène suivante</button></div><details><summary>Positions, conditions et contrôle de caméra</summary><pre id="metadata"></pre></details>
<h2 id="films">Ce que fait le véritable moteur</h2><p>Les activités rares sont des admissions déterministes sur les itinéraires du pilote. Elles utilisent le directeur, les appuis, l’animation et l’AudioContext réels. Elles sont séparées de la promenade ordinaire ; aucun film n’est une animation précalculée ou une bande-son ajoutée.</p><div class="films">'''+cards+'''</div>
<h2 id="mesures">Performances appariées</h2><p>Chromium / SwiftShader, rendu logiciel, 480 × 320. Les personnes, leurs tenues, la caméra, le ciel et les champs d’éclairage sont appariés. Valeurs médianes en millisecondes, pose et rendu synchronisé compris. Les distributions et P95 restent dans les données.</p><div class="scroll"><table><thead><tr><th>Scène</th><th>Profil</th><th>Personnes</th><th>Mission 22</th><th>22.1</th><th>Écart</th></tr></thead><tbody>'''+timings+'''</tbody></table></div><p class="note">Ces mesures ne certifient pas un GPU physique ou Android. Les mesures initiales et le cas Éco répété sont conservés ; elles ont guidé le niveau de détail des raccords d’articulations.</p><div class="links"><a href="performance.json">Mesures finales</a><a href="performance-before-joint-lod.json">Avant optimisation des articulations</a><a href="performance-foret-eco-repeat.json">Reprise du cas Éco</a><a href="walk.json">Promenade prolongée</a><a href="pont-native.json">Traversée native</a><a href="facades/before.json">Façades avant</a><a href="facades/after.json">Façades après</a></div>
<h2 id="sources">Ce qui est observé, reconstruit ou encore limité</h2><p>IGN LiDAR HD / MNT et OSM restent les sources géographiques. Le tablier conserve son axe et ses altitudes centrales ; la section transversale et le raccord de chaussée restent des reconstructions documentées. Le MNT n’est pas aplani. L’assise est au sol au jardin communal documenté par l’Office de tourisme ; aucun banc ou passage dans une façade n’est inventé.</p><p>Les personnages et leurs accessoires restent stylisés. Les entrées de bâtiments ne sont pas activées. Le repos public en fin de routine nocturne reste une limite. Les photographies accessibles ne sont pas traitées comme des relevés métriques.</p><div class="links"><a href="geometry.json">Préparation géométrique</a><a href="determinism.json">Reproduction indépendante</a><a href="preservation.json">Préservation des sources</a><a href="public-rest.json">Ancrages de repos</a><a href="audio-sources.json">Sources audio CC0</a><a href="../../public/audio/credits.html">Crédits audio</a></div><figure style="margin-top:24px"><img src="../mission-14-evidence/heritage/reference-pont-153575084.jpg" alt="Photographie documentaire du pont et du château"><figcaption>Photographie documentaire, Floppy36 — <a href="https://commons.wikimedia.org/wiki/File:Anglin_-_Angles-sur-l%27Anglin_(86)_-_Pont_et_Ch%C3%A2teau.jpg">Wikimedia Commons</a>, <a href="https://creativecommons.org/licenses/by-sa/4.0">CC BY-SA 4.0</a>. Réduction déjà archivée en Mission 14, aucune métrique précise déduite de la photo.</figcaption></figure><p><small>0 € supplémentaire · aucune fusion · aucun déploiement · Living Paintings / LP-01 inchangé.</small></p></main><script>
const scenes='''+data+''';const select=document.querySelector('#scene');scenes.forEach((r,i)=>select.add(new Option(r.label,i)));function show(){const r=scenes[Number(select.value)];document.querySelector('#before').src=r.before;document.querySelector('#after').src=r.after;document.querySelector('#metadata').textContent=JSON.stringify(r,null,2)}select.onchange=show;document.querySelector('#split').oninput=e=>document.querySelector('#after').style.clipPath='inset(0 0 0 '+e.target.value+'%)';document.querySelector('#previous').onclick=()=>{select.value=(Number(select.value)+scenes.length-1)%scenes.length;show()};document.querySelector('#next').onclick=()=>{select.value=(Number(select.value)+1)%scenes.length;show()};show();
</script></html>'''
text=text.replace('../../public/audio/credits.html','https://github.com/sebastienleidgens-lab/endless-earth/blob/mission/22-1-realisme-continuite/public/audio/credits.html')
(root/'index.html').write_text(text)
(root/'gallery-scenes.json').write_text(json.dumps({'rows':rows,'sameCamera':all(r['sameCamera']for r in rows),'comparisons':len(rows)},indent=2,ensure_ascii=False)+'\n')
